# illustrative (not in repo)
@dataclass(frozen=True)
class Acl:
    principal: str; resource: str; name: str; prefixed: bool; op: str; allow: bool

def authorized(acls, principal, resource, name, op) -> bool:
    match = [a for a in acls if a.principal in (principal, "User:*") and a.resource == resource
             and a.op in (op, "ALL") and (name.startswith(a.name) if a.prefixed else name == a.name)]
    if any(not a.allow for a in match):
        return False                     # DENY wins
    return any(a.allow for a in match)   # default deny

# illustrative (not in repo): byte-rate throttle per client
class ByteBucket:
    def __init__(self, rate: float, burst: float):
        self.rate, self.burst, self.tokens, self.t = rate, burst, burst, time.monotonic()
    def delay_for(self, nbytes: int) -> float:
        now = time.monotonic()
        self.tokens = min(self.burst, self.tokens + (now - self.t) * self.rate)
        self.t = now
        self.tokens -= nbytes                      # may go negative = debt
        return 0.0 if self.tokens >= 0 else -self.tokens / self.rate

# solution: add to minikafka/storage/log.py (class Log)
def offset_for_timestamp(self, ts_ms: int) -> int:
    # First offset whose timestamp >= ts_ms (Kafka offsetsForTimes). LEO if none.
    for seg in self.segments:
        if seg.max_timestamp < ts_ms:
            continue                                   # whole segment is older: skip without reading
        for rec in seg.read(seg.base_offset, seg.size + 1):
            if rec.timestamp >= ts_ms:
                return rec.offset
    return self.log_end_offset

# test
def test_offset_for_timestamp(tmp_path):
    log = Log(tmp_path, segment_bytes=300)
    for i in range(20):
        log.append([(None, b"v" * 50)], timestamp_ms=1000 + i * 10)
    assert log.offset_for_timestamp(0) == 0
    assert log.offset_for_timestamp(1055) == 6        # first ts >= 1055 is 1060 at offset 6
    assert log.offset_for_timestamp(10**12) == 20      # nothing newer -> LEO
